import{_ as o,o as e,c as i,ag as r}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"科学日报 · 2026-10-08（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-08.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-08.md"}'),a={name:"topics/ai-system-architecture/science-daily-2026-10-08.md"};function l(n,t,s,c,u,d){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="科学日报-·-2026-10-08-ai-系统架构" tabindex="-1">科学日报 · 2026-10-08（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-10-08-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-10-08（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> — 第31期</p></blockquote><hr><h2 id="把语言模型-改装-成按字节运行-nature" tabindex="-1">把语言模型&quot;改装&quot;成按字节运行（Nature） <a class="header-anchor" href="#把语言模型-改装-成按字节运行-nature" aria-label="Permalink to &quot;把语言模型&quot;改装&quot;成按字节运行（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> ｜ DOI: 10.1038/s41586-026-11111-4</p></blockquote><ul><li>问题：主流 LLM 用<strong>子词（subword）分词</strong>把文本切成 token，掩盖细粒度字符信息，对<strong>代码、生物序列</strong>等&quot;意义依赖单字符/字节&quot;的科学数据尤其不利；直接按字节建模的模型此前一直落后。</li><li>方法：提出通用的<strong>字节化（byteification）</strong>——用两阶段转换流程把已有子词模型改装成字节级模型，只需极少额外训练。</li><li>结果：改造后的字节级模型性能<strong>超过以往字节级模型，逼近子词系统</strong>。</li><li>洞察：tokenizer 是数据接口层，<strong>接口粒度决定了模型能看到什么</strong>。与本库 REPL/replay_eval&quot;输入结构决定可比性&quot;同构——换了表示层，能力边界随之改变。</li></ul><h2 id="agent-in-a-bottle-把通用能力-装瓶-成廉价可复用方案-arxiv-2610-08775" tabindex="-1">Agent in a Bottle：把通用能力&quot;装瓶&quot;成廉价可复用方案（arXiv:2610.08775） <a class="header-anchor" href="#agent-in-a-bottle-把通用能力-装瓶-成廉价可复用方案-arxiv-2610-08775" aria-label="Permalink to &quot;Agent in a Bottle：把通用能力&quot;装瓶&quot;成廉价可复用方案（arXiv:2610.08775）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> ｜ arXiv: 2610.08775</p></blockquote><ul><li>定义：把&quot;Agent 自主为百万级相关实例造出更便宜解法&quot;称为 <strong>bottling（装瓶）</strong>——把通用能力转成任务专用产物，在答案质量与<strong>摊销成本</strong>间权衡（可训小模型，或写可复用程序）。</li><li>基准：<strong>BOTTLED</strong>——Agent 收到一整批未标注负载，须在固定时间/算力/API 预算内完成。</li><li>数据：10 模型 × 3 任务，<strong>强零样本表现不能可靠转化为强装瓶能力</strong>；零样本相近的模型装瓶后差距明显；60 次装瓶有 <strong>31 次</strong>不如同等 token 预算下更强的两个小模型蒸馏基线。</li><li>洞察：<strong>&quot;会做&quot;≠&quot;会把自己变得不用做&quot;</strong>。这正是本库 RSI / Dream-RSI 的分水岭——一次性求解与把能力固化为可复用资产的差距，是 Agent 经济学的核心变量。</li></ul><h2 id="worldsolver-llm-agent-能否靠-生成求解器-模拟物理动态-arxiv-2610-08720" tabindex="-1">WorldSolver：LLM Agent 能否靠&quot;生成求解器&quot;模拟物理动态（arXiv:2610.08720） <a class="header-anchor" href="#worldsolver-llm-agent-能否靠-生成求解器-模拟物理动态-arxiv-2610-08720" aria-label="Permalink to &quot;WorldSolver：LLM Agent 能否靠&quot;生成求解器&quot;模拟物理动态（arXiv:2610.08720）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> ｜ arXiv: 2610.08720</p></blockquote><ul><li>背景：物理仿真的核心是 <strong>solver</strong>（计算系统状态随时间演化），造它需物理理解（选模型）+ 数学推理（写动力学）+ 软件工程（写代码）三位一体。</li><li>基准：<strong>WorldSolver</strong>——168 个仿真任务，取自 <strong>61 篇经典计算机图形论文</strong>的物理现象，横跨 <strong>7 个物理域</strong>；每个任务给固定仿真环境 + 代码骨架，<strong>求解器实现留给 Agent</strong>。</li><li>评估：从&quot;能否成功执行&quot;&quot;视觉保真度&quot;等维度打分。</li><li>洞察：把&quot;科学建模&quot;变成可自动评分的<strong>代码生成</strong>任务。与本库&quot;用源码本身扩 RL 环境&quot;（第29期 CodeMidas）同源——<strong>代码是可验证的通用接口</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第31期 AI 板块</p></blockquote><p>关键词：字节级语言模型、byteification、tokenizer、bottling、摊销成本、agent 经济学、WorldSolver、求解器生成、物理仿真、代码接口 关联：<code>topics/ai-system-architecture/dream-rsi.md</code>（一次性求解 vs 能力固化）、<code>topics/ai-system-architecture/science-daily-2026-09-22.md</code>（CodeMidas 用源码扩 RL 环境）、<code>topics/intelligence-self-learning/science-daily-2026-10-08.md</code>（Sherpa 因人施教）</p>',15)])])}const p=o(a,[["render",l]]);export{q as __pageData,p as default};
